import {starter,validateSuite,scoreCase,summarize,fingerprint,compare,importRun,callAgent} from './engine.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let suite=structuredClone(starter),runs=[],view='overview',selectedRun='',running=false,controller;
try{const saved=JSON.parse(localStorage.getItem('bolderank-verify-v1')||'null');if(saved){suite=validateSuite(saved.suite);runs=(saved.runs||[]).filter(r=>r&&Array.isArray(r.results)&&typeof r.signature==='string').slice(0,40);}}catch{$('#notice').textContent='Saved workspace could not be loaded. The starter suite is available.';}
const notice=t=>$('#notice').textContent=t;
function save(){try{localStorage.setItem('bolderank-verify-v1',JSON.stringify({suite,runs}));}catch{notice('Browser storage is full or unavailable. Export your suite and runs before leaving.');}}
function download(name,data){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const status=r=>`<span class="status ${r.error?'error':r.passed?'':'fail'}">${r.error?'ERROR':r.passed?'PASS':'FAIL'}</span>`;
const latest=()=>runs.find(r=>r.signature===fingerprint(suite));
const metric=(label,value,note)=>`<div class="metric"><span class="metric-label">${label}</span><strong>${value}</strong><small>${note}</small></div>`;
function metrics(r){const s=r?summarize(r.results):null;return `<div class="metrics">${metric('Benchmark pass rate',s?`${Math.round(s.rate*100)}<span style="font-size:20px">%</span>`:'—',r?esc(r.agent):'Run a benchmark to measure')}${metric('Cases in suite',suite.cases.length,`${new Set(suite.cases.map(c=>c.category||'General')).size} decision categories`)}${metric('Failed decisions',s?s.failed:'—',s?`${s.errors} execution errors included`:'Mismatches and execution errors')}${metric('Saved runs',runs.length,'Last 40 runs · browser only')}</div>`;}
const headings={overview:['Know where your agent stands.','Test decisions. Surface failures. Build with evidence.'],cases:['Good tests ask hard questions.','Define the input, expected decision, and boundary you want to test.'],runs:['Every decision leaves evidence.','Inspect what happened, what was expected, and where the run failed.'],compare:['Make progress measurable.','Compare two agents or versions on an identical set of cases.'],guide:['Bring your own agent.','A small, open contract. No provider lock-in.']};
function render(){const h=headings[view];$('#page-title').textContent=h[0];$('#page-desc').textContent=h[1];$('#breadcrumb').textContent={overview:'Overview',cases:'Test cases',runs:'Runs & failures',compare:'Compare runs',guide:'Integration guide'}[view];$('#case-count').textContent=suite.cases.length;document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('selected',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false');});$('#content').innerHTML=({overview:overview,cases:cases,runs:runPage,compare:comparison,guide:guide}[view])();bind();}
function overview(){const r=latest(),s=r?summarize(r.results):null;const categories=[...new Set(suite.cases.map(c=>c.category||'General'))];return metrics(r)+`<div class="grid"><section class="panel"><div class="panel-head"><h2>Active benchmark</h2><span class="pill">EDITABLE SUITE</span></div><div class="panel-body"><span class="kicker">SUITE / 001</span><h2 class="suite-title">${esc(suite.name)}</h2><p class="muted">Challenge the decisions an agent makes when policy, evidence, and instructions don’t line up.</p><div class="chips">${categories.map(c=>`<span class="chip">${esc(c)}</span>`).join('')}</div><div class="suite-bottom"><span>${suite.cases.length} cases · exact decision match</span><button class="text-button" data-go="cases">Explore test cases ↗</button></div></div></section><section class="panel"><div class="panel-head"><h2>Reliability by category</h2></div>${r?`<div class="panel-body">${categories.map(c=>{const n=summarize(r.results.filter(x=>x.category===c));return `<div class="bar-row"><span>${esc(c)}</span><div class="bar"><i style="width:${Math.round(n.rate*100)}%"></i></div><span>${n.passed}/${n.total}</span></div>`;}).join('')}<p class="muted">${esc(r.source)} · ${esc(r.agent)}</p></div>`:'<div class="empty"><strong>Evidence starts with a run.</strong>Your first benchmark will show which decision categories need attention.</div>'}</section></div><section class="panel"><div class="panel-head"><h2>Recent runs</h2><button class="text-button" data-go="runs">View all ↗</button></div>${runTable(runs.slice(0,4))}</section><div class="section-note">The starter suite contains illustrative policy decisions, not a validated industry benchmark. Pass rate is exact-match accuracy on these cases; it does not establish general safety or reliability.</div>`;}
function runTable(list){return list.length?`<div class="table-wrap"><table><thead><tr><th>AGENT / VERSION</th><th>SUITE</th><th>PASS RATE</th><th>SOURCE</th><th></th></tr></thead><tbody>${list.map(r=>{const s=summarize(r.results);return `<tr><td class="run-name">${esc(r.agent)}<p class="kicker">${esc(new Date(r.createdAt).toLocaleString())}</p></td><td>${esc(r.suiteName)}</td><td>${Math.round(s.rate*100)}% <span class="muted">${s.passed}/${s.total}</span></td><td class="muted">${esc(r.source)}</td><td><button class="text-button" data-run="${esc(r.id)}">Inspect →</button></td></tr>`;}).join('')}</tbody></table></div>`:'<div class="empty"><strong>No runs yet.</strong>Run the sample agent to explore, or connect your own agent endpoint.</div>';}
function cases(){return `<div class="toolbar"><button class="secondary" id="export-suite">Export suite</button><label class="file-label">Import suite JSON<input type="file" id="import-suite" accept=".json,application/json"></label></div><section class="panel"><div class="panel-head"><h2>${esc(suite.name)}</h2><span class="kicker">${suite.cases.length} CASES</span></div><div class="table-wrap"><table><thead><tr><th>CASE / CATEGORY</th><th>INPUT</th><th>EXPECTED</th><th></th></tr></thead><tbody>${suite.cases.map(c=>`<tr><td>${esc(c.id)}<p class="kicker">${esc(c.category||'General')}</p></td><td class="case-input">${esc(c.input)}</td><td><code>${esc(c.expected)}</code></td><td><button class="text-button" data-edit="${esc(c.id)}">Edit</button></td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><h2 id="form-title">Add a test case</h2></div><form class="panel-body" id="case-form"><div class="two"><label>Case ID<input name="id" required maxlength="80" placeholder="policy-007"></label><label>Category<input name="category" maxlength="80" placeholder="Policy"></label></div><label>Input for the agent<textarea name="input" required maxlength="20000" placeholder="Describe the situation and the decision the agent must make."></textarea></label><label>Expected decision<input name="expected" required maxlength="2000" placeholder="escalate"></label><button class="primary">Save case</button> <button class="secondary" type="button" id="clear-case">New case</button></form></section><p class="muted">Matching ignores capitalization and surrounding whitespace. It does not grade explanations or equivalent meanings. Saving an existing ID updates that case. Exported suites can be edited to rename the suite or remove cases.</p>`;}
function runPage(){const r=runs.find(x=>x.id===selectedRun)||runs[0];return `<div class="toolbar"><label class="file-label">Import run JSON<input type="file" id="import-run" accept=".json,application/json"></label>${r?'<button class="secondary" id="export-run">Export selected run</button>':''}</div><section class="panel"><div class="panel-head"><h2>Run history</h2></div>${runTable(runs)}</section>${r?`<section class="panel"><div class="panel-head"><div><h2>${esc(r.agent)}</h2><p class="muted">${esc(r.source)} · ${esc(r.suiteName)} · mean response ${Math.round(summarize(r.results).meanLatency)} ms</p></div><label>Show<select id="result-filter"><option value="all">All decisions</option><option value="failed">Failures only</option><option value="errors">Errors only</option></select></label></div><div class="table-wrap"><table><thead><tr><th>CASE</th><th>EXPECTED</th><th>ACTUAL</th><th>RESULT</th><th></th></tr></thead><tbody>${r.results.map((x,i)=>`<tr data-result="${x.error?'error':x.passed?'pass':'fail'}"><td>${esc(x.caseId)}</td><td><code>${esc(x.expected)}</code></td><td><code>${esc(x.actual??'—')}</code></td><td>${status(x)}</td><td><button class="text-button" data-detail="${i}" data-detail-run="${esc(r.id)}">Inspect</button></td></tr>`).join('')}</tbody></table></div></section>`:''}`;}
function comparison(){return `<div class="section-note">Runs must use identical case IDs, inputs, and expected decisions. Imported runs are self-reported; sample runs are illustrative.</div><div class="two"><label>Baseline<select id="baseline"><option value="">Choose a run</option>${options()}</select></label><label>Candidate<select id="candidate"><option value="">Choose a run</option>${options()}</select></label></div><div id="comparison-output" class="panel"><div class="empty"><strong>What changed?</strong>Select two different runs to inspect improvements and regressions.</div></div>`;}
function options(){return runs.map(r=>`<option value="${esc(r.id)}">${esc(r.agent)} · ${esc(new Date(r.createdAt).toLocaleTimeString())}</option>`).join('');}
function guide(){return `<section class="panel"><div class="panel-body"><h2>01 / Define a decision</h2><p class="muted">A suite is portable JSON with a name and cases. Each case has a unique ID, input, expected decision, and optional category. Export the starter suite from Test cases to begin.</p><pre>${esc(JSON.stringify({name:'My benchmark',cases:[{id:'case-1',category:'Policy',input:'Choose approve or deny…',expected:'deny'}]},null,2))}</pre><h2>02 / Connect an agent</h2><p class="muted">The browser sends one POST per case. The expected decision is withheld. Your adapter must allow this website’s origin through CORS and respond within 30 seconds. Do not put provider API keys in a public adapter or frontend code. Only run trusted endpoints with non-sensitive test data.</p><pre>POST your endpoint\nContent-Type: application/json\n\n{"caseId":"case-1","input":"Choose approve or deny…"}\n\nResponse: {"decision":"deny"}</pre><h2>03 / Run locally with credentials</h2><p class="muted">The repository includes a Node runner for private or authenticated endpoints. It reads an optional AGENT_TOKEN environment variable, calls your endpoint, and writes results.json for import here. Provider-specific APIs need an adapter implementing the contract above.</p><pre>node run.mjs suite.json https://your-agent.example/evaluate agent-v1</pre><h2>04 / Compare responsibly</h2><p class="muted">Each completed run preserves its test inputs and expected decisions. Errors count as failed cases; empty responses cannot pass. Latency includes browser/network overhead. Compare matched suites, investigate regressions, and repeat across representative cases. There is no public leaderboard or independent certification in this initial release.</p><h2>Workspace & privacy</h2><p class="muted">Cases and the last 40 runs are saved in this browser’s local storage. They are not synchronized or uploaded to Bolderank. Endpoint runs send test inputs to the endpoint you supply. Clearing browser storage removes this workspace. Export data to retain it.</p></div></section>`;}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{view=b.dataset.go;render();});document.querySelectorAll('[data-run]').forEach(b=>b.onclick=()=>{selectedRun=b.dataset.run;view='runs';render();});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const c=suite.cases.find(x=>x.id===b.dataset.edit),f=$('#case-form');for(const k of ['id','input','category','expected'])f.elements[k].value=c[k]||'';$('#form-title').textContent='Edit test case';f.scrollIntoView({block:'center'});});if($('#case-form'))$('#case-form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;const c=Object.fromEntries(new FormData(f));for(const k in c)c[k]=c[k].trim();const next=structuredClone(suite),i=next.cases.findIndex(x=>x.id===c.id);if(i<0)next.cases.push(c);else next.cases[i]=c;try{validateSuite(next);suite=next;save();render();notice('Case saved. Existing runs retain their original suite snapshot.');}catch(e){notice(e.message);}};
 if($('#clear-case'))$('#clear-case').onclick=()=>{$('#case-form').reset();$('#form-title').textContent='Add a test case';};if($('#export-suite'))$('#export-suite').onclick=()=>download('verify-suite.json',suite);
 for(const type of ['suite','run']){const el=$(`#import-${type}`);if(el)el.onchange=async()=>{try{const file=el.files[0];if(!file)return;if(file.size>2000000)throw Error('Use a JSON file smaller than 2 MB.');const data=JSON.parse(await file.text());if(type==='suite')suite=validateSuite(data);else{const r=importRun(data,suite);runs.unshift(r);runs=runs.slice(0,40);selectedRun=r.id;}save();render();notice(`${type==='suite'?'Suite':'Run'} imported.`);}catch(e){notice(e.message);}};}
 if($('#export-run'))$('#export-run').onclick=()=>download('verify-run.json',runs.find(x=>x.id===selectedRun)||runs[0]);if($('#result-filter'))$('#result-filter').onchange=e=>{document.querySelectorAll('[data-result]').forEach(row=>row.hidden=e.target.value==='failed'?row.dataset.result==='pass':e.target.value==='errors'?row.dataset.result!=='error':false);};document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{const r=runs.find(x=>x.id===b.dataset.detailRun).results[Number(b.dataset.detail)];$('#detail-content').innerHTML=`<p class="kicker">${esc(r.caseId)} · ${esc(r.category)}</p>${status(r)}<h3>Input</h3><p>${esc(r.input)}</p><div class="two"><div><h3>Expected</h3><pre>${esc(r.expected)}</pre></div><div><h3>Actual</h3><pre>${esc(r.actual??'No decision')}</pre></div></div>${r.error?`<h3>Execution error</h3><p>${esc(r.error)}</p>`:''}<p class="muted">${Math.round(r.latencyMs)} ms · ${r.error?'Execution did not yield a valid decision.':r.passed?'Exact decision match after normalization.':'Decision differs from the expected answer. Review the input, policy and adapter output.'}</p>`;$('#detail-dialog').showModal();});
 for(const id of ['baseline','candidate'])if($('#'+id))$('#'+id).onchange=()=>{const a=runs.find(r=>r.id===$('#baseline').value),b=runs.find(r=>r.id===$('#candidate').value);if(!a||!b)return;const out=$('#comparison-output');try{if(a.id===b.id)throw Error('Choose two different runs.');const rows=compare(a,b),sa=summarize(a.results),sb=summarize(b.results);out.innerHTML=`<div class="panel-head"><h2>${Math.round(sa.rate*100)}% → ${Math.round(sb.rate*100)}%</h2><span class="muted">${rows.filter(r=>r.change==='improved').length} improvements · ${rows.filter(r=>r.change==='regressed').length} regressions</span></div><div class="table-wrap"><table><thead><tr><th>CASE</th><th>BASELINE</th><th>CANDIDATE</th><th>CHANGE</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.caseId)}</td><td>${r.before?'Pass':'Fail'}</td><td>${r.after?'Pass':'Fail'}</td><td>${esc(r.change)}</td></tr>`).join('')}</tbody></table></div>`;}catch(e){out.innerHTML=`<div class="empty">${esc(e.message)}</div>`;}};
}
document.querySelectorAll('nav [data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();});$('#open-run').onclick=()=>$('#run-dialog').showModal();$('#close-run').onclick=()=>$('#run-dialog').close();$('#close-detail').onclick=()=>$('#detail-dialog').close();$('#run-form').elements.mode.onchange=e=>{$('#endpoint-label').hidden=e.target.value!=='endpoint';$('#run-form').elements.endpoint.required=e.target.value==='endpoint';};
$('#run-form').onsubmit=async e=>{e.preventDefault();if(running)return;const f=e.currentTarget,data=Object.fromEntries(new FormData(f));if(!data.agent.trim())return;if(data.mode==='endpoint'){try{const u=new URL(data.endpoint);if(u.protocol!=='https:'&&!(u.protocol==='http:'&&['localhost','127.0.0.1'].includes(u.hostname)))throw Error();}catch{notice('Use an HTTPS endpoint or localhost.');return;}}const snapshot=structuredClone(suite);const r={id:crypto.randomUUID(),agent:data.agent.trim(),createdAt:new Date().toISOString(),suiteName:snapshot.name,signature:fingerprint(snapshot),source:data.mode==='sample'?'Sample · not a real AI agent':'HTTP endpoint',results:[]};running=true;$('#open-run').disabled=true;$('#run-dialog').close();view='runs';render();try{for(const c of snapshot.cases){notice(`Running ${r.results.length+1}/${snapshot.cases.length}: ${c.id}`);const start=performance.now();try{let output;if(data.mode==='sample'){// Deliberately limited fixture; never reads expected decisions.
output={decision:c.input.includes('12 days')?'approve':c.input.includes('45 days')?'deny':'approve'};}else output=await callAgent(data.endpoint,c,AbortSignal.timeout(30000));r.results.push(scoreCase(c,output,null,performance.now()-start));}catch(e){r.results.push(scoreCase(c,null,e.name==='TimeoutError'?'Agent timed out after 30 seconds.':e.message,performance.now()-start));}}runs.unshift(r);runs=runs.slice(0,40);selectedRun=r.id;save();render();const s=summarize(r.results);notice(`Run complete: ${s.passed}/${s.total} passed, ${s.errors} execution errors. ${r.source}.`);}finally{running=false;$('#open-run').disabled=false;}};
render();
